  ('319d6256-bc12-4bdb-a499-4606eb5e177b', $$Natuurkunde$$, $$HAVO$$, $$Superaarde?$$, $$HAVO Natuurkunde 2022-III$$),
  ('81da8dea-9ae3-45e5-8800-1e0d08e7eb4d', $$Natuurkunde$$, $$HAVO$$, $$Concertharp$$, $$HAVO Natuurkunde 2022-III$$),
  ('d2e3ddbd-bf21-4d6f-b7c8-64d75b1e6082', $$Natuurkunde$$, $$HAVO$$, $$Wielrennen met een motor$$, $$HAVO Natuurkunde 2022-III$$),
  ('4a0b0ae1-36bb-460a-af80-ea81bff3db61', $$Natuurkunde$$, $$HAVO$$, $$Marathon onder de twee uur$$, $$HAVO Natuurkunde 2022-III$$),
  ('19dc8894-b567-49b7-a46b-2b0a3b7e40ee', $$Natuurkunde$$, $$HAVO$$, $$Theaterverlichting$$, $$HAVO Natuurkunde 2022-III$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('7b0b1ccd-56a4-4799-9321-67f6266a97b2', '319d6256-bc12-4bdb-a499-4606eb5e177b', $$intro exoplaneten; figuur 1 — planeet beweegt voor ster langs, lichtsterkte daalt tijdelijk$$, $$natuurkunde-havo-2022-iii-superaarde-context1.png$$, 496, $$Astronomen zijn voortdurend op zoek naar planeten bij andere sterren dan de zon. Deze zogenaamde exoplaneten zijn niet zichtbaar met een telescoop. Ze kunnen ontdekt worden door een tijd lang de lichtsterkte van een ster te meten. Als deze lichtsterkte niet constant is, dan kan dat veroorzaakt worden door een exoplaneet die voor de ster langs beweegt en daarbij het licht van de ster gedeeltelijk tegenhoudt. Zie figuur 1. Deze figuur is niet op schaal.

figuur 1: bovenaan een tekening van een planeet die in drie posities (1, 2, 3) langs een bolvormige ster beweegt; daaronder een grafiek van de lichtsterkte tegen de tijd, met een constante lichtsterkte die daalt zodra de planeet vóór de ster langs beweegt (rond posities 1 tot en met 3) en na positie 3 weer terugkeert naar de oorspronkelijke waarde.$$, 'inline'),
  ('6894f907-2fa2-4674-a4ab-1e6ac84db49f', '319d6256-bc12-4bdb-a499-4606eb5e177b', $$figuur 2 — tabel met massa, straal en omlooptijd van GJ1214b; λmax tussen 9,2·10⁻⁷ en 9,9·10⁻⁷ m$$, $$natuurkunde-havo-2022-iii-superaarde-context2.png$$, 496, $$Zo is bij de ster met de naam GJ1214 een exoplaneet ontdekt die de naam GJ1214b heeft gekregen. Er zijn veel verschillende soorten exoplaneten. Astronomen proberen exoplaneten te ordenen op basis van een aantal kenmerken. Zo kan ingeschat worden of een exoplaneet op de aarde lijkt en of er misschien leven mogelijk is. In figuur 2 staan enkele gegevens van exoplaneet GJ1214b.

figuur 2: tabel ''Exoplaneet GJ1214b'' met de rijen massa = 6,50·Maarde, straal = 2,76·raarde en omlooptijd rond ster = 37,92 uur.

De temperatuur aan het oppervlak van de ster is te bepalen door te meten aan het uitgezonden licht van de ster. Uit deze metingen blijkt dat de golflengte met de grootste intensiteit (λmax) ligt tussen 9,2·10⁻⁷ m en 9,9·10⁻⁷ m.$$, 'inline'),
  ('d1f327b6-0a24-42ca-a940-8170dc2f16ed', '319d6256-bc12-4bdb-a499-4606eb5e177b', $$figuur 3 — lichtsterkte-tijddiagram met vier pijlen A, B, C, D rond de dip$$, $$natuurkunde-havo-2022-iii-superaarde-context3.png$$, 496, $$Door het deels afdekken van het zichtbare oppervlak van de ster neemt de waargenomen lichtsterkte af. In figuur 3 is de gemeten lichtsterkte van de ster uitgezet tegen de tijd. Met behulp van deze figuur is de omlooptijd van de exoplaneet rond de ster te bepalen. In de figuur staan vier pijlen.

figuur 3: grafiek van de lichtsterkte (100% en 98,5% aangegeven) tegen de tijd, met twee gelijke dips die elk van 100% naar 98,5% dalen en weer terugkeren; pijl B geeft de breedte van de eerste dip aan, pijl A de tijd tussen het begin en het einde van de eerste dip, pijl C de tijd tussen het begin van de eerste dip en het begin van de tweede dip, en pijl D de tijd tussen het begin van de eerste dip en het einde van de tweede dip.$$, 'inline'),
  ('f7076647-416a-422b-9bdf-064b60680d9b', '319d6256-bc12-4bdb-a499-4606eb5e177b', $$oppervlakte ster 6,487·10¹⁶ m², 1,50% afgedekt; straal planeet 2,76·raarde met raarde=6,371·10⁶ m$$, $$natuurkunde-havo-2022-iii-superaarde-context4.png$$, 496, $$De oppervlakte van het cirkelvormige aanzicht van de ster is 6,487·10¹⁶ m². Uit de diepte van het dal in de lichtsterkte-metingen blijkt dat 1,50% hiervan is afgedekt door het cirkelvormige aanzicht van de planeet. Hiermee konden astronomen berekenen dat de straal van deze planeet 2,76 keer zo groot is als de straal van de aarde (raarde = 6,371·10⁶ m).$$, 'inline'),
  ('91f4f09e-8235-42d1-873c-cab7ef8e16fd', '319d6256-bc12-4bdb-a499-4606eb5e177b', $$valversnelling g hangt af van massa M en straal r van de planeet$$, $$natuurkunde-havo-2022-iii-superaarde-context5.png$$, 496, $$Om een exoplaneet te kunnen vergelijken met de aarde wordt onder andere de valversnelling g aan het oppervlak van die planeet bepaald. Deze valversnelling hangt af van de massa (M) en de straal (r) van de planeet.$$, 'inline'),
  ('3627f52d-8113-461d-92f2-6ea350e196a7', '319d6256-bc12-4bdb-a499-4606eb5e177b', $$intro dichtheidsbepaling exoplaneten t.o.v. de aarde$$, $$natuurkunde-havo-2022-iii-superaarde-context6.png$$, 496, $$Astronomen zijn op zoek naar exoplaneten die lijken op de rotsachtige aarde. Als de massa en de straal van de planeet GJ1214b bekend zijn, kan de dichtheid van die planeet worden berekend en vergeleken met die van de aarde.$$, 'inline'),
  ('cf0b7e00-5231-47c4-a1f7-088bdf5044da', '319d6256-bc12-4bdb-a499-4606eb5e177b', $$definitie ''superaarde'': rotsachtige planeet met massa tussen die van aarde en Uranus$$, $$natuurkunde-havo-2022-iii-superaarde-context7.png$$, 496, $$Astronomen proberen exoplaneten in te delen op basis van hun kenmerken. Uit de bepaling van de dichtheid volgde dat planeet GJ1214b een rotsachtige samenstelling heeft. Een rotsachtige planeet krijgt de indeling ''superaarde'' als de massa groter is dan de massa van de aarde, maar kleiner dan de massa van de planeet Uranus.$$, 'inline'),
  ('a8dc5ccf-2760-46c8-ab28-bfa4963726ca', '81da8dea-9ae3-45e5-8800-1e0d08e7eb4d', $$figuur 1 — concertharp; snaarlengte 37,9 cm, grondtoon 440 Hz; iedere snaar heeft grondtoon en boventonen$$, $$natuurkunde-havo-2022-iii-concertharp-context1.png$$, 496, $$Een concertharp is een snaarinstrument. Zie figuur 1. Na aanslaan van een snaar ontstaan er golven in de snaar en in de lucht.

figuur 1: foto van een vrouw die een concertharp bespeelt; de harp heeft een groot aantal snaren van verschillende lengte, gespannen tussen de hals en de romp van het instrument.

Een snaar wordt aangeslagen. De lengte van deze snaar is 37,9 cm. De snaar produceert een staande golf met een grondtoon van 440 Hz.

Bijzonder aan een concertharp is het grote aantal snaren. Zie figuur 1. Iedere snaar kan trillen met een grondtoon en (een veelvoud aan) boventonen. Op de uitwerkbijlage is een snaar getekend.$$, 'inline'),
  ('6e72cc55-106e-4645-bade-a15d61263d4b', '81da8dea-9ae3-45e5-8800-1e0d08e7eb4d', $$figuur 2 — aangeslagen snaar in uiterste stand met golfpatronen A, B, C, D$$, $$natuurkunde-havo-2022-iii-concertharp-context2.png$$, 496, $$Als bij een concertharp een snaar wordt aangeslagen ontstaan staande golven. In figuur 2 is een aangeslagen snaar getekend in de uiterste stand.

figuur 2: vier golfpatronen (aangeslagen snaar, A, B, C, D) van een trillende snaar tussen twee vaste vakverdelingen; de aangeslagen snaar staat in de uiterste (dikst getekende) stand, patronen A tot en met D tonen de snaar in verschillende, geleidelijk vlakker wordende standen.$$, 'inline'),
  ('4e0797dd-1c27-4332-b4f4-b80745263600', '81da8dea-9ae3-45e5-8800-1e0d08e7eb4d', $$figuur 3 en 4 — pedaal drukt pinnen tegen de snaar (pedaal los / pedaal ingetrapt); golfsnelheid constant$$, $$natuurkunde-havo-2022-iii-concertharp-context3.png$$, 496, $$Een concertharp heeft pedalen. Door het intrappen van een pedaal verdraait een wieltje en worden er twee pinnen tegen de snaar gedrukt. Zie figuur 3 en schematisch in figuur 4.

figuur 3: close-upfoto van een aantal harpsnaren met metalen pinnen en wieltjes bovenaan, waarbij een wit omcirkeld mechaniek de pinnen tegen een snaar drukt.
figuur 4: twee schematische tekeningen van eenzelfde snaar met een wieltje met twee pinnen; bij ''pedaal los'' raken de pinnen de snaar niet, bij ''pedaal ingetrapt'' is het wieltje gedraaid zodat de pinnen tegen de snaar gedrukt zijn en de snaar op die plek vastzetten.

De golfsnelheid in de snaar wordt als constant beschouwd.$$, 'inline'),
  ('b4483045-8a99-4d2e-a742-2409219652e8', '81da8dea-9ae3-45e5-8800-1e0d08e7eb4d', $$figuur 5 — oscillogram van een andere aangeslagen snaar, 2,0 ms per hokje$$, $$natuurkunde-havo-2022-iii-concertharp-context4.png$$, 496, $$Er wordt een andere snaar aangeslagen. Van de trilling is een oscillogram gemaakt. Zie figuur 5. De tijd is ingesteld op 2,0 ms per hokje.

figuur 5: oscillogram van een periodiek signaal dat per periode eerst een korte laagfrequente rimpeling onderaan laat zien, dan stijgt naar een piek met een kleine kartelrand, weer daalt en de rimpeling herhaalt; het patroon herhaalt zich regelmatig over de weergegeven tijd.$$, 'inline'),
  ('72ab8df8-e595-42c2-abc4-cbc44bc1af2e', '81da8dea-9ae3-45e5-8800-1e0d08e7eb4d', $$uitwerkbijlage vraag 7 — tabel om aan te kruisen of golven in snaar/lucht transversaal of longitudinaal zijn$$, $$natuurkunde-havo-2022-iii-concertharp-uitwerkbijlage-vraag7.png$$, 496, $$Uitwerkbijlage vraag 7: tabel met kolommen ''transversale golven'' en ''longitudinale golven'' en rijen ''golven in de snaar'' en ''golven in de lucht'', met lege vakjes om een kruisje in te zetten.$$, 'uitwerkbijlage'),
  ('f800376e-8f71-42fc-908e-c1f739139235', '81da8dea-9ae3-45e5-8800-1e0d08e7eb4d', $$uitwerkbijlage vraag 9 — verticale lijn (snaar) om het patroon van knopen en buiken op aan te geven$$, $$natuurkunde-havo-2022-iii-concertharp-uitwerkbijlage-vraag9.png$$, 496, $$Uitwerkbijlage vraag 9: een verticale lijn met aan beide uiteinden een vast punt, die de snaar voorstelt, waarop de leerling met letters K (knoop) en B (buik) het golfpatroon van de tweede boventoon moet aangeven.$$, 'uitwerkbijlage'),
  ('72038cca-4d25-410c-821f-53c7c19d4f89', 'd2e3ddbd-bf21-4d6f-b7c8-64d75b1e6082', $$intro verboden fietsmotor; figuur 1 — Pelektrisch=2,0·10² W, Pmechanisch=1,4·10² W$$, $$natuurkunde-havo-2022-iii-wielrennen-met-een-motor-context1.png$$, 496, $$Tijdens wielrenwedstrijden is hulp van een motor verboden. Tijdens een wedstrijd kan zo''n motor voor tijdwinst zorgen. In 2016 werd voor het eerst een racefiets ontdekt met een verboden motor in het frame.

De motor werkt op elektrische energie. Een deel van deze energie wordt door de motor gebruikt om arbeid te verrichten.
In figuur 1 is in een diagram weergegeven wat de motor aan elektrisch vermogen (Pelektrisch) krijgt en aan arbeid per seconde (mechanisch vermogen Pmechanisch) verricht. Deze figuur is niet op schaal.

figuur 1: energiestroomdiagram met drie pijlen: een lichtgrijze pijl ''Pelektrisch = 2,0·10² W'' die de ''motor'' (wit blok) binnenkomt, en twee pijlen die de motor verlaten: een lichtgrijze pijl ''Pmechanisch = 1,4·10² W'' en een donkergrijze (ongelabelde) pijl die het energieverlies voorstelt.$$, 'inline'),
  ('61614e59-1c0b-435c-abf1-c490472e1c94', 'd2e3ddbd-bf21-4d6f-b7c8-64d75b1e6082', $$Cauberg: hoogteverschil 64 m, wielrenner 80 kg levert 4,0·10² W, motor extra 1,4·10² W, wrijving verwaarloosd$$, $$natuurkunde-havo-2022-iii-wielrennen-met-een-motor-context2.png$$, 496, $$Een bij wielrenners bekende heuvel is de Cauberg. Deze heuvel heeft een hoogteverschil van 64 m.
Een wielrenner van 80 kg levert zelf een vermogen van 4,0·10² W tijdens de beklimming van de Cauberg. De motor levert continu een extra mechanisch vermogen van 1,4·10² W. Zie figuur 1. Alle wrijving wordt verwaarloosd.$$, 'inline'),
  ('3e5cadfa-20a7-4a58-8887-a1607f0eabcf', 'd2e3ddbd-bf21-4d6f-b7c8-64d75b1e6082', $$motor krijgt elektrisch vermogen 2,0·10² W; figuur 2 — tabel energiedichtheid en max. vermogen per kg voor NiCd en Li-ion$$, $$natuurkunde-havo-2022-iii-wielrennen-met-een-motor-context3.png$$, 496, $$De motor heeft een elektrisch vermogen van 2,0·10² W. Zie figuur 1.
De motor krijgt zijn energie van een accu. De accu is onzichtbaar ingebouwd in de fiets. In de tabel in figuur 2 zijn twee eigenschappen van verschillende types accu met elkaar vergeleken.

figuur 2: tabel met kolommen ''type accu'', ''energiedichtheid accu (Wh kg⁻¹)'' en ''maximaal vermogen per kilogram accu (W kg⁻¹)''; rij NiCd: 48 en 200; rij Li-ion: 220 en 400.$$, 'inline'),
  ('b8578010-3a0c-4007-8fde-131dc9672a64', 'd2e3ddbd-bf21-4d6f-b7c8-64d75b1e6082', $$Li-ion-accu gebruikt; accu mag max 0,80 kg wegen (anders opgemerkt)$$, $$natuurkunde-havo-2022-iii-wielrennen-met-een-motor-context4.png$$, 496, $$Voor de racefiets is een Li-ion-accu gebruikt. Tot voor kort werd in apparaten vooral gebruikgemaakt van NiCd-accu''s. Met NiCd konden geen bruikbare accu''s worden gemaakt voor racefietsen. In de fiets kan een accu verborgen worden van maximaal 0,80 kg. Een zwaardere (en grotere) accu zou opgemerkt worden.$$, 'inline'),
  ('04573b2c-f86e-4520-96bb-bd474830a531', 'd2e3ddbd-bf21-4d6f-b7c8-64d75b1e6082', $$Li-ion-accu met massa 0,80 kg$$, $$natuurkunde-havo-2022-iii-wielrennen-met-een-motor-context5.png$$, 496, $$Er is een Li-ion-accu gebruikt met een massa van 0,80 kg.$$, 'inline'),
  ('d69e2768-9e49-4f42-9b5a-7c6b853c8bc5', 'd2e3ddbd-bf21-4d6f-b7c8-64d75b1e6082', $$warmtedetectiecamera; figuur 3/4 — fietsen fotograferen, motor zichtbaar als lichte (warme) plek; drempel 2,0 °C, volume buis 48 cm³$$, $$natuurkunde-havo-2022-iii-wielrennen-met-een-motor-context6.png$$, 496, $$De motor en de accu zijn verstopt in een buis van de fiets.
Zo''n motor kan tijdens het fietsen worden opgespoord omdat hij warmte afgeeft. Met een speciale camera worden de fietsen gefotografeerd. Zie figuur 3. De camera laat met verschillende kleuren verschillen in temperatuur op de foto zien. De warme buis rond de motor komt licht op de foto. Zie figuur 4.

figuur 3: foto van een persoon die met een warmtebeeldcamera een groep geparkeerde racefietsen fotografeert.
figuur 4: warmtebeeldfoto van een fietsframe waarbij met een pijl een lichter (warmer) opgloeiend deel van de buis bij het frame wordt aangewezen, gelabeld ''motor''.

De camera kan het temperatuurverschil zichtbaar maken als het deel van de buis om de motor meer dan 2,0 °C warmer is dan de rest van de buis. Zie figuur 4. De motor moet dan wel lang genoeg hebben aangestaan. De buis is van aluminium en heeft rondom de motor een volume van 48 cm³. De motor heeft een elektrisch vermogen van 2,0·10² W en een mechanisch vermogen van 1,4·10² W. Zie figuur 1.$$, 'inline'),
  ('86b98a88-d54f-438a-8b63-d874d44980f7', 'd2e3ddbd-bf21-4d6f-b7c8-64d75b1e6082', $$röntgenscanner in aanhanger; figuur 5/6 — scan-opstelling en röntgenfoto fiets; medewerker 85 kg ontvangt 0,72 J per wedstrijddag, jaarlimiet 20 mGy$$, $$natuurkunde-havo-2022-iii-wielrennen-met-een-motor-context7.png$$, 496, $$Een motor in het frame kan ook voor of na de wedstrijd zichtbaar gemaakt worden door een röntgenfoto van de fiets te maken met een röntgenscanner die in een aanhanger ingebouwd is. Zie figuren 5 en 6.

figuur 5: foto van een geopende aanhanger met daarin een röntgenscanner waarin een racefiets hangt, met een medewerker die de fiets vasthoudt en een tweede medewerker die de scan bedient vanaf een laptop op een tafeltje naast de aanhanger.
figuur 6: röntgenfoto van het onderste deel van een fietsframe met trapas, kettingbladen, ketting en wiel; de ketting is duidelijk donkerder afgebeeld dan de even dikke aluminium buizen van het frame.

De röntgenscanner wordt gebruikt om de racefietsen op een wedstrijddag te scannen. Een medewerker (m = 85 kg) die in de aanhanger bij de scanner blijft staan, ontvangt gemiddeld 0,72 J aan röntgenstraling per wedstrijddag. Mensen die beroepshalve met straling werken, mogen jaarlijks over het lichaam een dosis van 20 mGy ontvangen.

Tijdens het scannen wordt het personeel aangeraden niet in de aanhanger met de scanner te blijven staan.$$, 'inline'),
  ('52ae456c-a645-48b3-b53e-0ccdba5358bc', 'd2e3ddbd-bf21-4d6f-b7c8-64d75b1e6082', $$figuur 6 toont: foto lichter bij meer röntgenstraling; ketting donkerder dan aluminium buizen; motor van metaal, deze fiets zonder motor$$, $$natuurkunde-havo-2022-iii-wielrennen-met-een-motor-context8.png$$, 496, $$In figuur 6 is te zien dat de foto lichter wordt als meer röntgenstraling de foto heeft bereikt. De ketting wordt donkerder afgebeeld dan de even dikke aluminium buizen van het frame.
Een motor is gemaakt van metaal. De fiets in figuur 6 blijkt geen motor in het frame te hebben.$$, 'inline'),
  ('e7c0f02d-557f-487c-9f45-edcd0563b6c4', 'd2e3ddbd-bf21-4d6f-b7c8-64d75b1e6082', $$uitwerkbijlage vraag 19 — drie zinnen met bestraald/besmet, grotere/kleinere halveringsdikte, donkerder/lichter om te omcirkelen$$, $$natuurkunde-havo-2022-iii-wielrennen-met-een-motor-uitwerkbijlage-vraag19.png$$, 496, $$Uitwerkbijlage vraag 19: ''De fiets is bestraald / besmet tijdens de scan.'', ''Het aluminium van het frame heeft een grotere / kleinere halveringsdikte dan het materiaal waarvan de ketting is gemaakt.'' en ''Een buis met motor zou donkerder / lichter op de foto te zien zijn geweest dan een buis zonder motor.'', met de alternatieven om te omcirkelen.$$, 'uitwerkbijlage'),
  ('1a68aa5f-f8b4-465c-8a05-ba98af75f06b', '4a0b0ae1-36bb-460a-af80-ea81bff3db61', $$intro marathonrecord 2014 (2u2m57s); figuur 1 — (s,t)-diagram wereldrecord$$, $$natuurkunde-havo-2022-iii-marathon-onder-de-twee-uur-context1.png$$, 496, $$Tijdens een marathon wordt een afstand van 42 km en 195 m in een zo kort mogelijke tijd gerend. In 2014 werd het wereldrecord gelopen in 2 uur, 2 minuten en 57 seconden. In figuur 1 staat het (vereenvoudigde) (s,t)-diagram dat hoort bij dit wereldrecord.

figuur 1: (s,t)-diagram met s (·10³ m, 0 tot 45) op de verticale as en t (h, 0 tot 2,5) op de horizontale as; een rechte, door de oorsprong lopende lijn tot ongeveer (2,05; 42).$$, 'inline'),
  ('0cb5a279-1a58-413b-b0f1-619a3fe2d974', '4a0b0ae1-36bb-460a-af80-ea81bff3db61', $$recordpoging 2017 onder de 2 uur; figuur 2 — auto''s geven tempo aan volgens nieuw loopschema o.b.v. record 2014$$, $$natuurkunde-havo-2022-iii-marathon-onder-de-twee-uur-context2.png$$, 496, $$Een looptijd van minder dan twee uur werd lang onmogelijk geacht. Atleten hebben in 2017 geprobeerd dat toch te halen door onder perfecte omstandigheden te lopen. In de voorbereiding werd het (s,t)-diagram van het wereldrecord uit 2014 als richtpunt gebruikt voor een nieuw loopschema voor deze recordpoging. Vóór de atleten zou een auto rijden om het tempo aan te geven volgens dat nieuwe schema. Zie figuur 2.

figuur 2: foto van twee auto''s op een racecircuit die een groep marathonlopers voorafgaan; op de achterste auto staat een display met de verstreken tijd.

Op de uitwerkbijlage staan drie zinnen over het (v,t)-diagram voor de recordpoging onder de twee uur.$$, 'inline'),
  ('e862b035-4888-4d73-b30e-e3bb4528601f', '4a0b0ae1-36bb-460a-af80-ea81bff3db61', $$circuit Monza met rechte stukken I en II; wind waait langs stuk I$$, $$natuurkunde-havo-2022-iii-marathon-onder-de-twee-uur-context3.png$$, 496, $$In het nieuwe schema kon nog geen rekening gehouden worden met de wind. Met tegenwind loopt een atleet langzamer, met wind mee loopt hij harder. De race werd gelopen op een deel van het autoracecircuit van Monza. Dit deel van het circuit heeft twee lange rechte stukken I en II. Tijdens de recordpoging was er wind. Zie figuur 3.

figuur 3: schematische bovenaanzichttekening van een ovaal circuit met looprichting tegen de klok in; het rechte stuk I (bovenaan, bij de start) heeft een windpijl vwind in dezelfde richting als de looprichting daar, het andere rechte stuk II ligt onderaan.$$, 'inline'),
  ('410ce231-fea1-4546-97ba-8c714c39f395', '4a0b0ae1-36bb-460a-af80-ea81bff3db61', $$wind: 0,3 m/s langzamer op stuk I, 0,3 m/s sneller op stuk II; stellingen van Anke en Bert$$, $$natuurkunde-havo-2022-iii-marathon-onder-de-twee-uur-context4.png$$, 496, $$Met deze wind loopt een atleet 0,3 m s⁻¹ langzamer dan hij zou lopen zonder wind op het rechte stuk I en 0,3 m s⁻¹ sneller dan hij zou lopen zonder wind op het rechte stuk II.

Anke beweert: “Een constante wind heeft geen invloed op de looptijd van een hele ronde.”
Bert beweert: “Door de wind wordt de looptijd voor een hele ronde langer.”$$, 'inline'),
  ('0ff94353-afcb-4582-a9c7-27f30990d985', '4a0b0ae1-36bb-460a-af80-ea81bff3db61', $$Kipchoge; hazen lopen vlak voor hem; figuur 4 — foto van lopers in groep$$, $$natuurkunde-havo-2022-iii-marathon-onder-de-twee-uur-context5.png$$, 496, $$Een van de atleten was Eliud Kipchoge. Om het lopen voor Kipchoge makkelijker te maken, renden er extra lopers (de zogenaamde hazen) vlak voor hem. Zie figuur 4.

figuur 4: foto van een groep hardlopers op een atletiekbaan die dicht opeen in een groepje rennen.$$, 'inline'),
  ('d0d9fc4a-b851-4c4e-b8ea-0db4802876fa', '4a0b0ae1-36bb-460a-af80-ea81bff3db61', $$figuur 5 — bovenaanzicht: lucht stroomt via de hazen om Kipchoge heen$$, $$natuurkunde-havo-2022-iii-marathon-onder-de-twee-uur-context6.png$$, 496, $$Er kan worden aangenomen dat dankzij de hazen een deel van de lucht om Kipchoge heen beweegt. Zie het bovenaanzicht in figuur 5.

figuur 5: bovenaanzichtschema met twee stroomlijnen die zich verbreden rond een groep grijze cirkels (de hazen) en weer samenkomen; de zwarte cirkel (Kipchoge) bevindt zich net achter de hazen, met pijlen die de bewegingsrichting van de lucht en van de atleten aangeven.$$, 'inline'),
  ('9afb0310-9dbd-474a-b907-9c72405bb985', '4a0b0ae1-36bb-460a-af80-ea81bff3db61', $$in de groep loopt voorste haas met groter vermogen P dan Kipchoge$$, $$natuurkunde-havo-2022-iii-marathon-onder-de-twee-uur-context7.png$$, 496, $$In de groep loopt de voorste haas met een groter vermogen P dan Kipchoge.$$, 'inline'),
  ('4cfe8c62-44b4-4e7c-807c-09574c383ec1', '4a0b0ae1-36bb-460a-af80-ea81bff3db61', $$Kipchoge eindigt in 2u25s, laatste ronde 5,84 m/s; circuit 2,4 km in 5 gelijke segmenten; figuur 6 — schema segmenten a t/m e$$, $$natuurkunde-havo-2022-iii-marathon-onder-de-twee-uur-context8.png$$, 496, $$Helaas is de poging destijds niet gelukt: Kipchoge eindigde in een tijd van 2 uur en 25 seconde met een snelheid van 5,84 m s⁻¹ in de laatste ronde. Het circuit is 2,4 km lang.
In figuur 6 is het circuit verdeeld in 5 gelijke segmenten: ab, bc, cd, de, ea.

figuur 6: schematische bovenaanzichttekening van hetzelfde ovale circuit (lengte 2,4 km) met looprichting tegen de klok in, waarbij de start/finish bij punt a ligt en de punten b, c, d en e het circuit verdelen in vijf gelijke segmenten (ab, bc, cd, de, ea).$$, 'inline'),
  ('c2740b66-36eb-4ae3-8cde-1815e1322ab2', '4a0b0ae1-36bb-460a-af80-ea81bff3db61', $$uitwerkbijlage vraag 20 — leeg (v,t)-assenstelsel met invulregels voor de berekening$$, $$natuurkunde-havo-2022-iii-marathon-onder-de-twee-uur-uitwerkbijlage-vraag20.png$$, 496, $$Uitwerkbijlage vraag 20: leeg (v,t)-diagram met v (m s⁻¹, 0 tot 9,0) op de verticale as en t (h, 0 tot 2,5) op de horizontale as, gevolgd door invulregels bij ''Berekening:'' om het antwoord toe te lichten.$$, 'uitwerkbijlage'),
  ('b3611670-acb5-4bed-8c48-0fd200337721', '4a0b0ae1-36bb-460a-af80-ea81bff3db61', $$uitwerkbijlage vraag 21 — drie zinnen over het (v,t)-diagram met langer/gelijk/korter e.d. om te omcirkelen$$, $$natuurkunde-havo-2022-iii-marathon-onder-de-twee-uur-uitwerkbijlage-vraag21.png$$, 496, $$Uitwerkbijlage vraag 21: ''In het (v,t)-diagram voor de lopers die onder de twee uur wilden lopen: is de looptijd langer dan / gelijk aan / korter dan die van het oude wereldrecord.'', ''is de gemiddelde snelheid hoger dan / gelijk aan / lager dan die van het oude wereldrecord.'' en ''is de oppervlakte onder de grafiek groter dan / gelijk aan / kleiner dan de oppervlakte onder de (v,t)-grafiek van het oude wereldrecord.'', met de alternatieven om te omcirkelen.$$, 'uitwerkbijlage'),
  ('c4d04b88-b4dc-4298-8618-08e42e2831b8', '19dc8894-b567-49b7-a46b-2b0a3b7e40ee', $$intro: lampen aan balk bevestigd; figuur 1/2 — balk op de grond en opgehesen aan het plafond$$, $$natuurkunde-havo-2022-iii-theaterverlichting-context1.png$$, 496, $$Theaterpodia worden verlicht met lampen. Deze lampen moeten voor iedere show anders worden opgehangen. Om dat veilig te doen, worden de lampen op de grond aan een balk bevestigd. Zie figuur 1. Deze balk wordt vervolgens met twee staalkabels opgehesen naar het plafond. Zie figuur 2.

figuur 1: foto van een lange balk met lampen en bekabeling die met twee hijskettingen op de grond van een podium ligt.
figuur 2: foto van een truss met een groot aantal theaterlampen, opgehangen tegen het dak van een gebouw.$$, 'inline'),
  ('d7906b22-1e5b-4a3e-8efe-decfb6cd7067', '19dc8894-b567-49b7-a46b-2b0a3b7e40ee', $$balk met lampen op schaal getekend op uitwerkbijlage; zwaartepunt Z gegeven, draaipunt D = linker kabel; totale massa 230 kg$$, $$natuurkunde-havo-2022-iii-theaterverlichting-context2.png$$, 496, $$Op de uitwerkbijlage is schematisch en op schaal een balk met lampen getekend. De verdeling van de (niet-afgebeelde) lampen is niet gelijk; de ligging van het zwaartepunt Z van balk en lampen samen is weergegeven. De bevestiging van de linker kabel wordt als draaipunt D beschouwd. De totale massa is 230 kg.$$, 'inline'),
  ('a20184e4-16fb-4033-a1e0-a85e7500a4cb', '19dc8894-b567-49b7-a46b-2b0a3b7e40ee', $$rekstrook-sensor op staalkabel (figuur 3); rekstrook is zigzagdraad op flexibel folie (figuur 4)$$, $$natuurkunde-havo-2022-iii-theaterverlichting-context3.png$$, 496, $$Als de staalkabels te zwaar belast worden, kunnen ze vervormen en breken. Om de vervorming van een staalkabel te meten kan er een sensor op bevestigd worden. Zie figuur 3. In deze sensor zit een rekstrook. Dit is een lange draad die zigzag op een flexibel folie is bevestigd. Zie figuur 4.

figuur 3: foto van een deel van een staalkabel met daarop een cilindervormige sensor bevestigd, gelabeld ''staalkabel'' en ''sensor''.
figuur 4: tekening van een rekstrook: een lange draad die in een smal zigzagpatroon over een rechthoekig stuk folie loopt en aan één kant uitmondt in twee brede aansluitvlakken.$$, 'inline'),
  ('82f82459-91da-4abb-86b9-a28c012da3b7', '19dc8894-b567-49b7-a46b-2b0a3b7e40ee', $$weerstand rekstrook neemt toe bij uitrekken; figuur 5 — methode 1 (langs de kabel) en methode 2 (dwars om de kabel)$$, $$natuurkunde-havo-2022-iii-theaterverlichting-context4.png$$, 496, $$De rekstrook werkt volgens het principe dat de elektrische weerstand ervan toeneemt doordat tijdens het uitrekken de draad op het folie langer en dunner wordt.

Een rekstrook kan in verschillende richtingen op de staalkabel bevestigd zijn. Zie figuur 5.

figuur 5: twee tekeningen van eenzelfde cilindervormige staalkabel met daarop een rekstrook bevestigd; bij methode 1 loopt de zigzagdraad van de rekstrook in de lengterichting van de kabel, bij methode 2 loopt de zigzagdraad dwars (rondom) de kabel.$$, 'inline'),
  ('8dd4aa10-1014-4f17-800b-9930af55cb24', '19dc8894-b567-49b7-a46b-2b0a3b7e40ee', $$rekstrook in serie met vaste weerstand op 5,0 V; figuur 6 — sensorspanning U tegen relatieve rek ε$$, $$natuurkunde-havo-2022-iii-theaterverlichting-context5.png$$, 496, $$De rekstrook wordt in serie met een vaste weerstand aangesloten op een spanningsbron van 5,0 V. De weerstand van de draad in de rekstrook neemt toe als de rekstrook wordt uitgerekt. Met een voltmeter wordt de spanning over een van de twee weerstanden gemeten tijdens het uitrekken van de staalkabel. Deze elektrische sensorspanning is uitgezet tegen de relatieve rek van de staalkabel. Zie figuur 6.

figuur 6: grafiek van de sensorspanning U (V, onderbroken schaal van 0 naar 2,50 tot 2,54) tegen de relatieve rek ε (%, 0 tot 0,15); een rechte, stijgende lijn vanaf (0; 2,50) tot ongeveer (0,15; 2,537).$$, 'inline'),
  ('d957750f-4079-4346-b2b8-22c3ea60ebf1', '19dc8894-b567-49b7-a46b-2b0a3b7e40ee', $$veiligheidsgrens mechanische spanning σ < 2,4·10⁸ Nm⁻²; gemeten sensorspanningen 2,520 V en 2,510 V$$, $$natuurkunde-havo-2022-iii-theaterverlichting-context6.png$$, 496, $$Met de elektrische sensorspanning wordt bepaald of de mechanische spanning in de staalkabel niet te hoog is. Om de lampen veilig op te hangen moet de mechanische spanning σ in iedere kabel minder zijn dan 2,4·10⁸ Nm⁻².
Na het monteren van een aantal lampen bedraagt de elektrische sensorspanning voor de ene kabel 2,520 V en voor de andere kabel 2,510 V. Figuur 6 staat ook op de uitwerkbijlage.$$, 'inline'),
  ('e96ccafc-7808-4861-924a-2e0eead03b8b', '19dc8894-b567-49b7-a46b-2b0a3b7e40ee', $$uitwerkbijlage vraag 25 — balk op schaal met kabels I en II, draaipunt D en zwaartepunt Z$$, $$natuurkunde-havo-2022-iii-theaterverlichting-uitwerkbijlage-vraag25.png$$, 496, $$Uitwerkbijlage vraag 25: schematische, op schaal getekende balk met daarop een zigzagpatroon; kabel I is bevestigd aan het linkeruiteinde bij draaipunt D, kabel II aan het rechteruiteinde; het zwaartepunt Z van balk en lampen samen is aangegeven op een punt dichter bij D dan bij het rechteruiteinde.$$, 'uitwerkbijlage'),
  ('057418ab-5d8e-4bf4-a489-75bc2c027c22', '19dc8894-b567-49b7-a46b-2b0a3b7e40ee', $$uitwerkbijlage vraag 28 — dezelfde grafiek van figuur 6 met invulregels bij ''Bepaling:''$$, $$natuurkunde-havo-2022-iii-theaterverlichting-uitwerkbijlage-vraag28.png$$, 496, $$Uitwerkbijlage vraag 28: dezelfde grafiek als figuur 6 van de sensorspanning U tegen de relatieve rek ε, gevolgd door invulregels bij ''Bepaling:'' om de berekening te noteren.$$, 'uitwerkbijlage');

