   $$natuurkunde-havo-2022-iii-concertharp-vraag7.png$$, 496, $$2p 7 Geef in de tabel op de uitwerkbijlage voor elk van deze golven met een kruisje aan of deze voornamelijk transversaal of voornamelijk longitudinaal zijn.$$, array['a8dc5ccf-2760-46c8-ab28-bfa4963726ca','72ab8df8-e595-42c2-abc4-cbc44bc1af2e']::uuid[]),
