   $$natuurkunde-havo-2022-iii-concertharp-vraag11.png$$, 496, $$2p 11 Leg uit of de grondtoon door het intrappen van het pedaal lager of hoger gaat klinken.$$, array['4e0797dd-1c27-4332-b4f4-b80745263600']::uuid[]),
  ('44e3d92f-e6c1-4a60-af57-66560e486bd5', '81da8dea-9ae3-45e5-8800-1e0d08e7eb4d', 12,
